d:#fff8e7;border:1px solid var(--line);box-shadow:5px 6px 0 #ddd0ac;padding:24px;position:relative;transform:rotate(-.4deg)}.memo:before{content:"FIELD MANUAL / PAGE 0";display:block;border-bottom:1px dashed var(--line);padding-bottom:14px;margin-bottom:20px;font:700 11px var(--mono);letter-spacing:.15em;color:var(--red)}.memo h3{font-size:clamp(1.5rem,3vw,2.2rem);letter-spacing:-.04em;margin:0 0 12px}.quote{font-size:clamp(1.1rem,2.6vw,1.5rem);line-height:1.4;margin:0 0 18px}.question{font:700 12px/1.5 var(--mono);text-transform:uppercase;letter-spacing:.08em;border-top:1px dashed var(--line);padding-top:17px}.options{display:grid;gap:10px}.option{width:100%;text-align:left;border:1.5px solid var(--ink);background:transparent;padding:15px 14px;display:flex;gap:14px;align-items:flex-start;line-height:1.32;transition:transform .15s,background .15s,box-shadow .15s}.option:hover:not(:disabled){transform:translate(-3px,-3px);box-shadow:4px 4px 0 var(--ink);background:#fff8e8}.option b{font:700 13px var(--mono);color:var(--red)}.option:disabled{cursor:default}.option.correct{background:var(--mint);border-color:#427650}.option.wrong{background:#f1c5ae;border-color:var(--red)}.toolrow{display:flex;gap:14px;align-items:center;flex-wrap:wrap;margin-top:16px}.hint{background:none;border:0;border-bottom:1px dashed var(--ink);padding:3px 0;font:700 12px var(--mono)}.hint-text{font-size:14px;line-height:1.45;margin:12px 0 0;padding:10px 12px;background:#f8e6bc;border-left:3px solid var(--gold)}.feedback{margin-top:25px;padding:19px 22px;background:var(--ink);color:var(--paper);border-left:6px solid var(--gold);animation:rise .25s ease-out}.feedback strong{display:block;font-size:1.35rem;margin-bottom:7px}.feedback p{margin:0;line-height:1.45}.next{display:inline-block;background:var(--red);color:white;border:2px solid var(--ink);padding:12px 18px;margin-top:18px;font:700 12px var(--mono);text-transform:uppercase;letter-spacing:.07em;box-shadow:4px 4px 0 var(--ink)}.next:hover{transform:translate(2px,2px);box-shadow:2px 2px 0 var(--ink)}.progress{display:flex;gap:5px;margin:0 0 20px}.tick{height:6px;background:#d3c3a1;flex:1}.tick.done{background:var(--red)}.tick.current{background:var(--gold)}.end{max-width:650px;margin:20px auto;text-align:center;border:3px double var(--ink);padding:32px 20px;background:#fff8e7;animation:rise .5s ease-out}.end .rank{font:700 11px var(--mono);letter-spacing:.18em;color:var(--red)}.end h3{font-size:clamp(2rem,5vw,3.8rem);line-height:1;margin:17px 0}.end p{line-height:1.5}.foot{border-top:2px solid var(--ink);padding:20px 6% 27px;display:flex;justify-content:space-between;gap:18px;flex-wrap:wrap;font:12px/1.5 var(--mono)}.foot a{text-underline-offset:3px}.hidden{display:none!important}@keyframes rise{from{opacity:0;transform:translateY(9px)}to{opacity:1;transform:translateY(0)}}@media(max-width:690px){.shell{padding:8px}.mast{padding:12px 16px}.hero{grid-template-columns:1fr}.hero-copy{padding:38px 22px 27px}.hero-art{border-left:0;border-top:2px solid var(--ink);height:260px;min-height:0}.hero-art img{max-height:none}.strip{padding:11px 16px;font-size:10px}.desk{padding:28px 20px 42px}.case{grid-template-columns:1fr;gap:22px}.memo{padding:19px}.desk-head{align-items:end}.foot{padding:20px}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;scroll-behavior:auto!important;transition-duration:.01ms!important}}
