<section class="hero"><div class="hero-copy"><span class="eyebrow">Case files · No. 001—005</span><h1>The Unhelpful <em>Manual</em> Bureau.</h1><p class="lede">Five appliances. Five baffling instructions. One brave reader who can tell a power switch from a philosophical suggestion.</p></div><figure class="hero-art" style="margin:0"><img src="manual-museum-machine.webp" alt="Vintage technical illustration of an impossible brass and glass machine with a crescent moon in its chamber"><figcaption>Exhibit A · the machine in question</figcaption></figure></section>
<div class="strip"><span>Confidential: probably safe to operate</span><span id="scoretop">0 / 5 decoded</span></div>
<section class="desk" aria-label="Manual decoding game"><div class="progress" id="progress" aria-label="Case progress"></div><div class="desk-head"><h2 id="heading">Incoming case file</h2><span class="counter" id="counter">01 / 05</span></div><div id="game"><div class="case"><article class="memo"><h3 id="device"></h3><p class="quote" id="excerpt"></p><p class="question" id="question"></p></article><div><div class="options" id="options" role="group" aria-label="Choose an interpretation"></div><div class="toolrow"><button class="hint" id="hint" type="button">Request marginal note ↗</button><span id="hintflag" class="eyebrow"></span></div><p class="hint-text hidden" id="hinttext"></p></div></div><div class="feedback hidden" id="feedback" role="status" aria-live="polite"><strong id="verdict"></strong><p id="explanation"></p><button id="next" class="next" type="button">Next case →</button></div></div><div class="end hidden" id="end" aria-live="polite"><span class="rank">Official bureau assessment</span><h3 id="endtitle"></h3><p id="endtext"></p><button class="next" id="again" type="button">Reopen the files ↻</button></div></section>
<footer class="foot"><span>Inspired by Jon’s <a href="https://jona.ca/2004/09/hall-of-technical-documentation.html">Hall of Technical Documentation Weirdness</a>. These manuals are original fiction.</span><span>No actual machines were harmed.</span></footer>
</main></div>
<script>
'use strict';
const cases=[
 {device:'The Moonlight Toaster',excerpt:'“Before first use, orient the crescent upward. Depress the lunar key only after the chamber has ceased glowing; never reverse the sequence unless breakfast is desired yesterday.”',question:'When should you press the lunar key?',options:['While the chamber is glowing','After the chamber stops glowing','Before you turn the crescent upward'],answer:1,hint:'“Only after” is doing the heavy lifting here.',explain:'Wait for the glow to stop, then press the lunar key. The yesterday-breakfast warranty is famously limited.'},
 {device:'The Pocket Weather Engine',excerpt:'“In the event of indoor rain, rotate the brass dial toward CLEAR. The blue lever is for storage only and must remain raised during operation.”',question:'It is raining indoors. What is the safe move?',options:['Lower the blue lever and wait','Turn the brass dial toward CLEAR, leaving the lever raised','Turn the brass dial toward STORM'],answer:1,hint:'One control changes weather; the other changes storage mode.',explain:'CLEAR on the brass dial; blue lever up. If the ceiling remains damp, consult your landlord.'},
 {device:'The Automatic Bookmark Rewinder',excerpt:'“To recover a lost page, insert one ribbon into the right slot. A second ribbon cancels the first. Pull the red tab only once the bell has rung twice.”',question:'Which sequence recovers your page?',options:['Insert two ribbons, pull immediately','Insert one ribbon, wait for two bells, pull the red tab','Pull the red tab, then insert one ribbon'],answer:1,hint:'The number of ribbons and bells both matter.',explain:'One ribbon, two bells, then the tab. This is the closest any manual has come to poetry.'},
 {device:'The Portable Silence Cabinet',excerpt:'“For quiet mode, close the velvet hatch while the amber lamp is lit. Should the lamp go dark, open the hatch and restart; do not close it in darkness.”',question:'The amber lamp goes dark before you close the hatch. Now what?',options:['Close the hatch quickly anyway','Open the hatch and restart','Wait with the hatch closed'],answer:1,hint:'The last sentence specifically forbids one tempting shortcut.',explain:'Open and restart. Apparently even silence has a startup sequence.'},
 {device:'The Tea-Leaf Telegraph',excerpt:'“A steady green needle means transmission is complete. A pulsing green needle means transmission is still in progress. Remove the cup only upon steady indication.”',question:'The green needle is pulsing. Can you remove the cup?',options:['Yes, green always means done','No, wait until the needle is steady','Only if you stir clockwise first'],answer:1,hint:'Color alone is insufficient; watch the needle’s behavior.',explain:'Wait for steady green. The cup is the antenna, which may explain the taste.'}
];
const $=id=>document.getElementById(id);let order=[],index=0,score=0,locked=false;
function shuffle(list){const a=[...list];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function reset(){order=shuffle(cases);index=0;score=0;$('end').classList.add('hidden');$('game').classList.remove('hidden');render()}
function render(){locked=false;const c=order[index];$('heading').textContent='Incoming case file';$('counter').textContent=String(index+1).padStart(2,'0')+' / 05';$('scoretop').textContent=score+' / 5 decoded';$('device').textContent=c.device;$('excerpt').textContent=c.excerpt;$('question').textContent=c.question;$('hintflag').textContent='';$('hinttext').textContent=c.hint;$('hinttext').classList.add('hidden');$('hint').disabled=false;$('feedback').classList.add('hidden');$('next').textContent=index===4?'Read assessment →':'Next case →';$('progress').replaceChildren(...cases.map((_,n)=>{const e=document.createElement('span');e.className='tick'+(n<index?' done':n===index?' current':'');return e}));const opts=c.options.map((label,n)=>({label,n}));$('options').replaceChildren(...shuffle(opts).map((o,position)=>{const b=document.createElement('button');b.className='option';b.type='button';b.dataset.choice=o.n;const mark=document.createElement('b');mark.textContent=String.fromCharCode(65+position);const label=document.createElement('span');label.textContent=o.label;b.append(mark,label);b.addEventListener('click',()=>choose(o.n));return b}))}
function choose(choice){if(locked)return;locked=true;const c=order[index],correct=choice===c.answer;if(correct)score++;$('scoretop').textContent=score+' / 5 decoded';for(const b of $('options').children){const n=Number(b.dataset.choice);b.disabled=true;if(n===c.answer)b.classList.add('correct');else if(n===choice)b.classList.add('wrong')}$('hint').disabled=true;$('verdict').textContent=correct?'STAMPED: DECODED ✓':'STAMPED: OPERATING ERROR ✕';$('explanation').textContent=c.explain;$('feedback').classList.remove('hidden')}
function advance(){if(!locked)return;if(index<4){index++;render();$('heading').scrollIntoView({block:'start',behavior:'smooth'})}else{showEnd()}}
function showEnd(){$('game').classList.add('hidden');$('end').classList.remove('hidden');$('heading').textContent='Case files closed';$('counter').textContent='05 / 05';$('progress').replaceChildren(...cases.map(()=>{const e=document.createElement('span');e.className='tick done';return e}));$('endtitle').textContent=score===5?'Chief Interpreter':score>=3?'Licensed Manual Wrangler':'Apprentice of the Fine Print';$('endtext').textContent=score+' of 5 impossible manuals successfully decoded. '+(score===5?'The Bureau trusts you with its most dangerous appliance: the office printer.':score>=3?'Excellent work. The remaining machines are being kept under supervision.':'The Bureau recommends a second reading and a strong cup of tea.');$('end').scrollIntoView({block:'nearest',behavior:'smooth'})}
$('hint').addEventListener('click',()=>{if(locked)return;$('hinttext').classList.remove('hidden');$('hintflag').textContent='note opened';$('hint').disabled=true});$('next').addEventListener('click',advance);$('again').addEventListener('click',reset);reset();
</script>
</body></html>
